use filmcraft_project::{Project,ItemId,TrackItem};use filmcraft_time::Tick;use serde_json::{Value,json};
fn clip(i:&TrackItem,t:Tick)->Value{json!({"clip":i.id,"item":i.item,"frame":i.source_time_at(t),"parameters":i.effect_time_at(t),"generator":t-i.start})}
fn main(){let fixture:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let base=&fixture["cases"][0];let sid=base["sequence"].as_u64().unwrap();let mut cases=vec![];const T:i64=254016000000;
for mode in 0..32{let mut p:Project=serde_json::from_value(base["document"]["project"].clone()).unwrap();let q=p.sequence_mut(ItemId(sid)).unwrap();let tr=&mut q.video_tracks[0];tr.enabled=mode%8!=1;
for(i,c)in tr.items.iter_mut().enumerate(){c.start=Tick(i as i64*2*T);c.duration=Tick(2*T);c.source_in=Tick(T);c.speed=if mode&2!=0{1.5}else{1.};c.reverse=mode&4!=0;c.enabled=!(mode&8!=0&&i==0);c.frame_hold=if mode&16!=0{Some(Tick(7*T))}else{None};c.hold_filters=mode%3==0;}
let a=tr.items[0].id;let b=tr.items[1].id;tr.transitions.clear();if mode%4!=0{tr.transitions.push(serde_json::from_value(json!({"id":999,"effect":{"effect":"cross_dissolve","params":{},"enabled":true},"start":T,"duration":2*T,"from":if mode%5==0{None}else{Some(a)},"to":if mode%7==0{None}else{Some(b)},"align":"CenterAtCut","reverse":mode%2!=0})).unwrap());}
let mut upper=tr.clone();upper.id=filmcraft_project::TrackId(333);upper.enabled=mode%3!=0;for c in &mut upper.items{c.id=filmcraft_project::ClipId(c.id.0+10000);}upper.transitions.clear();q.video_tracks.push(upper);
for at in [-1,0,1,T-1,T,T+1,2*T-1,2*T,2*T+1,3*T-1,3*T,3*T+1,4*T-1,4*T,7*T,9007199254740993]{let t=Tick(at);let q=p.sequence(ItemId(sid)).unwrap();let mut layers=vec![];
for tr in &q.video_tracks{if !tr.enabled{continue}if let Some(x)=tr.transitions.iter().find(|x|x.range().contains(t)){let side=|id:Option<filmcraft_project::ClipId>|id.and_then(|id|tr.item(id)).filter(|i|i.enabled).map(|i|clip(i,t));layers.push(json!({"kind":"transition","track":tr.id,"id":x.id,"from":side(x.from),"to":side(x.to),"progress":x.progress(t),"reverse":x.reverse,"effect":x.effect}));continue}if let Some(i)=tr.item_at(t).filter(|i|i.enabled){layers.push(json!({"kind":"clip","track":tr.id,"clip":clip(i,t)}));}}
cases.push(json!({"document":{"format":"filmcraft.project","schema_version":12,"project":p},"sequence":sid,"mode":mode,"at":at,"layers":layers}));}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
